class Solution:
    def canReachCorner(self, xCorner, yCorner, circles):
        n = len(circles)
        par = list(range(n))
        def find(a):
            while par[a] != a:
                par[a] = par[par[a]]; a = par[a]
            return a
        def segHit(x1, y1, x2, y2, cx, cy, r):
            dx, dy = x2 - x1, y2 - y1
            L2 = dx * dx + dy * dy
            t = 0 if L2 == 0 else max(0.0, min(1.0, ((cx - x1) * dx + (cy - y1) * dy) / L2))
            px, py = x1 + t * dx, y1 + t * dy
            return (px - cx) ** 2 + (py - cy) ** 2 <= r * r
        def inRect(px, py):
            return 0 <= px <= xCorner and 0 <= py <= yCorner
        def hit(i, j):
            x1, y1, r1 = circles[i]; x2, y2, r2 = circles[j]
            d2 = (x1 - x2) ** 2 + (y1 - y2) ** 2
            if d2 > (r1 + r2) ** 2 or d2 < (r1 - r2) ** 2: return False
            d = d2 ** 0.5
            if d == 0: return inRect(x1, y1)
            a = (d2 + r1 * r1 - r2 * r2) / (2 * d)
            h = max(0.0, r1 * r1 - a * a) ** 0.5
            mx, my = x1 + a * (x2 - x1) / d, y1 + a * (y2 - y1) / d
            ox, oy = -(y2 - y1) / d * h, (x2 - x1) / d * h
            return inRect(mx + ox, my + oy) or inRect(mx - ox, my - oy)
        for i in range(n):
            for j in range(i + 1, n):
                if hit(i, j): par[find(i)] = find(j)
        marks = {}
        for i, (x, y, r) in enumerate(circles):
            f = find(i)
            m = marks.setdefault(f, set())
            if segHit(0, 0, 0, yCorner, x, y, r): m.add(0)
            if segHit(xCorner, 0, xCorner, yCorner, x, y, r): m.add(1)
            if segHit(0, yCorner, xCorner, yCorner, x, y, r): m.add(2)
            if segHit(0, 0, xCorner, 0, x, y, r): m.add(3)
        return all(len(m) < 2 for m in marks.values())

