            if(d2>(r1+r2)*(r1+r2)||d2<(r1-r2)*(r1-r2)) continue;
            long double d=sqrtl(d2);
            bool conn=false;
            if(d==0) conn=inRect(x1,y1);
            else{
                long double a=(d2+r1*r1-r2*r2)/(2*d);
                long double h=sqrtl(max((long double)0.0,r1*r1-a*a));
                long double mx=x1+a*(x2-x1)/d,my=y1+a*(y2-y1)/d;
                long double ox=-(y2-y1)/d*h, oy=(x2-x1)/d*h;
                conn=inRect(mx+ox,my+oy)||inRect(mx-ox,my-oy);
            }
            if(conn) par[find(i)]=find(j);
        }
        vector<set<int>> marks(n);
        for(int i=0;i<n;i++){
            long double x=circles[i][0],y=circles[i][1],r=circles[i][2];
            auto& m=marks[find(i)];
            if(segHit(0,0,0,Y,x,y,r)) m.insert(0);
            if(segHit(X,0,X,Y,x,y,r)) m.insert(1);
            if(segHit(0,Y,X,Y,x,y,r)) m.insert(2);
            if(segHit(0,0,X,0,x,y,r)) m.insert(3);
