var canReachCorner = function(X, Y, circles) {
    const n = circles.length, par = [...Array(n).keys()];
    const find = a => { while (par[a] !== a) { par[a] = par[par[a]]; a = par[a]; } return a; };
    const inRect = (x, y) => x >= 0 && x <= X && y >= 0 && y <= Y;
    const segHit = (x1,y1,x2,y2,cx,cy,r) => {
        const dx = x2-x1, dy = y2-y1, L2 = dx*dx+dy*dy;
        const t = L2 === 0 ? 0 : Math.max(0, Math.min(1, ((cx-x1)*dx+(cy-y1)*dy)/L2));
        const px = x1+t*dx, py = y1+t*dy;
        return (px-cx)**2 + (py-cy)**2 <= r*r;
    };
    for (let i = 0; i < n; i++) for (let j = i+1; j < n; j++) {
        const [x1,y1,r1] = circles[i], [x2,y2,r2] = circles[j];
        const d2 = (x1-x2)**2 + (y1-y2)**2;
        if (d2 > (r1+r2)**2 || d2 < (r1-r2)**2) continue;
        const d = Math.sqrt(d2); let conn = false;
        if (d === 0) conn = inRect(x1, y1);
        else {
            const a = (d2 + r1*r1 - r2*r2) / (2*d);
            const h = Math.sqrt(Math.max(0, r1*r1 - a*a));
            const mx = x1 + a*(x2-x1)/d, my = y1 + a*(y2-y1)/d;
            const ox = -(y2-y1)/d*h, oy = (x2-x1)/d*h;
            conn = inRect(mx+ox, my+oy) || inRect(mx-ox, my-oy);
        }
        if (conn) par[find(i)] = find(j);
    }
    const marks = Array.from({length: n}, () => new Set());
    circles.forEach(([x, y, r], i) => {
        const m = marks[find(i)];
        if (segHit(0,0,0,Y,x,y,r)) m.add(0);
        if (segHit(X,0,X,Y,x,y,r)) m.add(1);
        if (segHit(0,Y,X,Y,x,y,r)) m.add(2);
        if (segHit(0,0,X,0,x,y,r)) m.add(3);
    });
    return marks.every(m => m.size < 2);
};
